GWEI_PER_ETH = 10**9

def eip1559(gas_used, base_fee, max_priority, max_fee):
    """Ritorna None se la tx non è includibile, altrimenti un dict in gwei."""
    if max_fee < base_fee:
        return None                       # non copre neppure la base fee
    tip = min(max_priority, max_fee - base_fee)   # tip effettivo per gas
    return {
        "prezzo_effettivo": base_fee + tip,
        "pagato": gas_used * (base_fee + tip),
        "bruciato": gas_used * base_fee,
        "al_validatore": gas_used * tip,
    }

for maxfee in (200, 110, 90):
    r = eip1559(21000, 100, 20, maxfee)
    if r is None:
        print(f"maxFee={maxfee}: non inclusa (resta pending)")
    else:
        print(f"maxFee={maxfee}: " + ", ".join(
            f"{k}={v/GWEI_PER_ETH:.5f} ETH" if k != "prezzo_effettivo" else f"{k}={v} gwei"
            for k, v in r.items()))

def rlp(x) -> bytes:
    """RLP (Recursive Length Prefix): x è bytes, int >= 0 o lista annidata."""
    if isinstance(x, int):                      # interi: big-endian senza zeri iniziali
        x = x.to_bytes((x.bit_length() + 7) // 8, "big")
    if isinstance(x, (bytes, bytearray)):
        if len(x) == 1 and x[0] < 0x80:
            return bytes(x)                     # un byte "piccolo" codifica se stesso
        return _len_prefix(len(x), 0x80) + bytes(x)
    payload = b"".join(rlp(e) for e in x)       # lista: concatena le codifiche
    return _len_prefix(len(payload), 0xC0) + payload

def _len_prefix(n, offset):
    if n <= 55:
        return bytes([offset + n])
    ln = n.to_bytes((n.bit_length() + 7) // 8, "big")
    return bytes([offset + 55 + len(ln)]) + ln

def hex_prefix(nibbles, leaf: bool) -> bytes:
    """Hex-Prefix encoding dei cammini (nibble) nei nodi leaf/extension del MPT."""
    flag = (2 if leaf else 0) + (len(nibbles) % 2)
    ns = [flag] + ([] if len(nibbles) % 2 else [0]) + list(nibbles)
    return bytes(ns[i] * 16 + ns[i + 1] for i in range(0, len(ns), 2))

tests = [b"dog", [b"cat", b"dog"], b"", [], 0, 15, 1024, [[], [[]], [[], [[]]]],
         b"Lorem ipsum dolor sit amet, consectetur adipisicing elit"]
for t in tests:
    print(repr(t)[:30].ljust(32), rlp(t).hex())
print("HP ext  [1,2,3,4,5]   ->", hex_prefix([1, 2, 3, 4, 5], False).hex())
print("HP ext  [0,1,2,3,4,5] ->", hex_prefix([0, 1, 2, 3, 4, 5], False).hex())
print("HP leaf [0,f,1,c,b,8] ->", hex_prefix([0, 0xf, 1, 0xc, 0xb, 8], True).hex())
print("HP leaf [f,1,c,b,8]   ->", hex_prefix([0xf, 1, 0xc, 0xb, 8], True).hex())
